rows=list(csv.DictReader((ROOT/'03_translation/tables/game.csv').open(encoding='utf-8-sig')))
by={r['id']:r for r in rows};data={x[i]['id']:t for i,t in edits.items()}
# Only the approved character identity is normalized in unreviewed lines.
aliases={}
for r in rows:
 if 'credits' in r['id'] or any(w in r['id'].lower() for w in ['legal','eula','license']):continue
 if re.search(r'\bGiul\b',r['source'],re.I) and re.search(r'(?<![\u0621-\u064a])جيول(?![\u0621-\u064a])',r['target']):
  aliases[r['id']]=re.sub(r'(?<![\u0621-\u064a])جيول(?![\u0621-\u064a])','غيول',r['target'])
tags=re.compile(r'<[^>]+>|\{[^}]+\}|%\d*\$?[sdif]|\\[nrt]')
for k,t in data.items():assert collections.Counter(tags.findall(by[k]['target']))==collections.Counter(tags.findall(t)),k
aliases={k:v for k,v in aliases.items() if k not in data}
(ROOT/'03_translation/story_context_r2.json').write_text(json.dumps(data,ensure_ascii=False,indent=2)+'\n',encoding='utf-8')
(ROOT/'03_translation/story_names_r2.json').write_text(json.dumps(aliases,ensure_ascii=False,indent=2)+'\n',encoding='utf-8')
print(json.dumps(dict(manual_contexts=len(data),name_only_consistency=len(aliases))))
